-- GENERATED by `wfj generate` from data/gossip/gossip-33.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["330ecf4282b48e8e"] = { "Soldato, mostra un po' di pietà al tenente Reethe.", "." },
  ["331a7eaa7e6ad94c"] = { "Questo completo fa proprio risaltare l'azzurro dei miei occhi, non trovi? Dovrebbe essere evidente che di talento ne ho da vendere, quindi posso permettermi di svelarti qualcuno dei miei trucchi del mestiere. Ascolta bene, d'accordo?", "." },
  ["331c7cae59072031"] = { "Informazioni... Con i nostri esploratori e i nostri agenti controlliamo il flusso delle informazioni a Lordaeron. I movimenti del Flagello, i suoi possedimenti, tutto sotto i nostri occhi vigili...", "." },
  ["331cf5ab88ddac49"] = { "Fermi! Vermi, voi questo lo chiamate combattere? È patetico! Ora metteteci il cuore, tanto non vi serve più!", "." },
  ["33217b0814980fd1"] = { "È davvero un mistero del passato! Ma anche una chiave per il nostro futuro!", "." },
  ["3324f74db58e4631"] = { "Ssserenità... finalmentesss!", "." },
  ["3326e94ee7c7fe24"] = { "Kroshius vivo? Kroshius schiaccia!", "." },
  ["333321d44c349693"] = { "<Thrall ride.>\n\nC'è ancora così tanto da imparare, {race}.\n\nSei troppo giovane per ricordare le guerre e i massacri delle epoche passate. Troppo giovane per ricordare il peso della maledizione portata dal nostro popolo.\n\nLa nostra posizione con l'⟦Alliance=Alleanza⟧ al momento è precaria. Scaramucce e battaglie minori avvengono, ma c'è pace: qualcosa che il nostro popolo non conosceva da millenni. Rinunceresti a tutto questo per gettarci di nuovo nelle fauci del caos, ma contro un nuovo nemico? Uno che non si fermerà finché non saremo tutti distrutti?", "." },
  ["3335296d54c4f41f"] = { "Sembra che l'esercito del Flagello sia arrivato a Tanaris. Un numero considerevole delle sue necropoli e di altre forze è stato inviato lì.\n\nNecropoli rimanenti: $2283W", "." },
  ["333dc655b6684d98"] = { "Una fenditura temporale si apre e ne emerge %s!", "." },
  ["333e7980f0918000"] = { "Non respirerai più!", "." },
  ["333ec183aa4ad845"] = { "%s si pavoneggia con passo pesante.", "." },
  ["3340533ebf761ca3"] = { "Prego, buona giornata.", "." },
  ["334589cebe5d8b96"] = { "Cosa piace mangiare a Dadanga?", "." },
  ["3346d37f9cc660ea"] = { "I lingotti sono solo in esposizione!", "." },
  ["3347503aacf34dff"] = { "Benvenuti, tutti quanti, alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧, il più grande evento del mondo intero! Abbiamo di tutto... cibo delizioso, bevande forti, manufatti esotici, letture del futuro, premi straordinari ed emozioni senza fine! Non dimenticate di consegnare i vostri Darkmoon Faire Prize Ticket a Gelvas Grimegate! Ne bastano cinque o più e siete sulla strada per i premi più meravigliosi di tutta Azeroth. Tutti vincono!", "." },
  ["334adcef17724e42"] = { "Parlami dei cimiteri.", "." },
  ["33559eb0c56f68ad"] = { "Uscire di qui senza una lama nella schiena o il veleno nelle vene sarebbe già un'impresa.", "." },
  ["33581f36d40ee504"] = { "Presto conoscerete il prezzo della vostra intromissione, mortali... Il padrone è quasi integro... E quando si leverà, il vostro mondo cesserà di esistere.", "." },
  ["335c73259bc8ea63"] = { "Sarà rapido, ma non indolore!", "." },
  ["3360566d1f7995c8"] = { "Fai di questa locanda la tua casa.", "." },
  ["3361360585d2b02b"] = { "Al maniero non si parla d'altro che del tuo arrivo, <padrone/padrona> {name}. Siamo tutti onorati e lusingati dalla tua presenza.", "." },
  ["336169b2ca175577"] = { "Lo senti, <straniero/straniera>? Il ronzio si fa più forte ogni giorno che passa. Devono essere questi cristalli a far impazzire questi insetti.", "." },
  ["3367483eb768708e"] = { "Sì, ti prego.", "." },
  ["336f3b1ce8adb47a"] = { "Non voglio avere niente a che fare con ⟦Silithus=Silitus⟧, i Qiraji e men che meno con quei dannati draghi!", "." },
  ["337740bc70d1edef"] = { "Ecco il segatronchi rubato! Fermatelo, o Lugwizzle ci farà la pelle!", "." },
  ["3379d4274319308a"] = { "Sì, Remulos. Prepara le razze mortali.", "." },
  ["33854260995a1532"] = { "Perché mi hai ucciso, {name}?", "." },
  ["33858108e73289d2"] = { "Non lasciate passare nessuno!", "." },
  ["338d94cfa782c36b"] = { "Prendi la chiave e apri queste catene! Ce l'ha Hitah'ya the Keeper... in fondo alla grotta...", "." },
  ["338eaf1651496c4f"] = { "Ma guarda chi si vede, {name}! Che bello rivederti; non so come esprimerti tutta la mia gratitudine per l'aiuto che hai dato finora a me e alle mie invenzioni.\n\nCosa posso fare per te oggi?", "." },
  ["33905716e49a0032"] = { "%s fruga tra i teschi...", "." },
  ["33932af7c2d10d89"] = { "Per una volta sono d'accordo con te... feccia.", "." },
  ["33978143f47dff3e"] = { "Grazie, {name}. Ora il mio spirito troverà finalmente pace.", "." },
  ["3397aa8bfeeb8147"] = { "Come stavo dicendo, ho tenuto quel frammento dello scettro per ben cinquecento anni e non mi ha dato che guai. Attirava ogni genere di attenzioni, del genere sbagliato. Voglio che mi si lasci in pace con i miei studi, non fare da balia al biglietto per la gloria di qualche aspirante eroe. Così... l'ho dato al pesce.", "." },
  ["339aee5df54a646b"] = { "Un altro modo? Racconta...", "." },
  ["339bd1324a2d0303"] = { "Il pesce è squisito, Jessica.", "." },
  ["33aad5e6a20c50ce"] = { "Il Consiglio di ⟦Duskwood=Boscovespro⟧ deve agire. Il male aleggia nell'aria.", "." },
  ["33ab2c82af0f9a56"] = { "%s si agita in un sonno inquieto.", "." },
  ["33aca3db81161a47"] = { "Credo che il tuo primo esercizio sarà scavare una miniera fino a ⟦Undercity=Sepulcra⟧. Eh, capito? Miniera... lascia perdere. Per arrivare a ⟦Undercity=Sepulcra⟧ va' sul retro delle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧, a sud di Brill, e prendi l'ascensore per scendere. Lì chiedi ulteriore aiuto a uno degli Undercity Guardian.", "." },
  ["33b2019434d59be4"] = { "È ora di picchiare!", "." },
  ["33b2ccf80a4f2820"] = { "Cominciamo una nuova battaglia, e stavolta battiamo l'⟦Horde=Orda⟧!", "." },
  ["33b6e488e6278ce7"] = { "Le Vette di ⟦Stonetalon=Petrartiglio⟧ nascondono molte caverne pericolose in tutta questa regione. Esplorarle può riservare molte avventure a chi è disposto a rischiare la vita per la gloria.\n\n{class}, forse cerchi ricchezze che solo seguendo il tuo cuore e la tua anima puoi ottenere.", "." },
  ["33bc264b2e3e73fe"] = { "%s emerge dalla pianta, permettendole di guarire.", "." },
  ["33bf3341f20825c7"] = { "Mi viene l'acquolina in bocca solo a pensarci. Pyall Silentstride è il miglior cuoco del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Lo trovi nella grande tenda all'angolo nord-ovest del villaggio.", "." },
  ["33bf403328eff2ea"] = { "Dov'è l'anziano Bellowrage?", "." },
  ["33c8293780b50902"] = { "Mi sa che ti serve un passaggio per attraversare il Grande Mare. Beh, sei nel posto giusto: questo è l'ormeggio della Maiden's Fancy, la miglior nave passeggeri che solchi queste acque. Quando arriva, sali a bordo e, prima che te ne accorga, ti ritroverai a crogiolarti sulle spiagge sabbiose di Rovotorto.", "." },
  ["33cc6ee5364ff3bd"] = { "Dov'è l'anziano Morningdew?", "." },
  ["33d38c522a70603b"] = { "Abbi pazienza!\n\n<Bodley borbotta qualcosa sottovoce sull'impazienza dei vivi>\n\nCome stavo dicendo, lo spirito di Sire Valthalak e gli assassini spettrali, evocati con i suoi trastulli negromantici, cominciarono ad assalirci. Te lo dico io, a quel punto non eravamo in condizione di reagire, quindi scappammo. Ricordo ancora Mor Grayhoof, uno dei nostri druidi, scivolare e cadere a un certo punto nei livelli inferiori della guglia.\n\nIl resto, come si dice, è storia.", "." },
  ["33ddeb9aa05480ea"] = { "Vorrei addestrarmi!", "." },
  ["33e00c0137106293"] = { "Chiedi a Kibler del tesoro! SQUAWK!", "." },
  ["33e474963d8855eb"] = { "Sono Bolvar Fordragon, Gran Signore di ⟦Stormwind=Roccavento⟧.", "." },
  ["33e838cdd76b1007"] = { "{name} ha assaltato le stalle!", "." },
  ["33eaa945ca6552f6"] = { "Hanno fatto irruzione nella Hall of Lights! Dobbiamo fermare gli intrusi!", "." },
  ["33f4dda6e26c3596"] = { "Sento l'odore della tua paura, {race}.", "." },
  ["33f6fe4b8130c3c9"] = { "Ok, prepariamo questo globo...", "." },
  ["33f7eed396559e5f"] = { "È davvero un'arma pregevole, {name}. Guidi gli spiriti come pochi che abbia mai conosciuto. Ascoltali, e ti guideranno come tu hai guidato loro. Va', cerca l'orco di nome Kelgruk Bloodaxe. Non parla con gli spiriti ma li ascolta, e le sue armi sono le migliori su cui abbia mai posato gli occhi.", "." },
  ["33fda0a832e3ac57"] = { "Torniamo al boschetto, mortale.", "." },
  ["33fdb965523d99fd"] = { "Per chi mi hai preso, per il gran mogol degli incantatori? Le tue abilità richiedono la guida di uno Specialista! Va' a cercare Kitta Firewind alla ⟦Tower of Azora=Torre di Azora⟧.", "." },
  ["33fec2564464265b"] = { "Me paura! Me scappa ora!", "." },
})
